-- Aggregated listing price floor/ceiling per location, used to advise
-- prospects on the home-request budget step.
CREATE TABLE "upward_area_price_guide" (
    "id" SERIAL NOT NULL,
    "uuid" TEXT NOT NULL,
    "state" TEXT NOT NULL,
    "area" TEXT NOT NULL,
    "subArea" TEXT,
    "bedrooms" INTEGER NOT NULL,
    "baths" INTEGER,
    "minPrice" DOUBLE PRECISION NOT NULL,
    "maxPrice" DOUBLE PRECISION NOT NULL,
    "sampleSize" INTEGER NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "upward_area_price_guide_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "upward_area_price_guide_uuid_key" ON "upward_area_price_guide"("uuid");

-- CreateIndex
CREATE INDEX "upward_area_price_guide_state_area_bedrooms_idx" ON "upward_area_price_guide"("state", "area", "bedrooms");

-- CreateIndex
CREATE UNIQUE INDEX "upward_area_price_guide_state_area_subArea_bedrooms_baths_key" ON "upward_area_price_guide"("state", "area", "subArea", "bedrooms", "baths");

-- Seed data aggregated from client/apps/web/public/export.csv (Nov 2025 rental listing scrape).
-- Filters applied: status='ok', price_period='year' only (blank period = for-sale price, excluded),
-- group-relative outlier guard (values outside 10x the group median dropped),
-- absolute sanity ceiling of NGN 150,000,000/year, and a minimum of 3 samples per group.





